mapper.select:
SELECT principal_name,
       COUNT(*) AS login_count,
       MIN(access_token_issued_at) AS first_login_at,
       MAX(access_token_issued_at) AS last_login_at
FROM oauth2_authorization
WHERE authorization_grant_type = #{grantType}
  AND access_token_issued_at >= #{windowStart}
  AND access_token_issued_at < #{windowEnd}
GROUP BY principal_name
